{
  "name": "opencode-codegraph",
  "version": "0.1.38",
  "description": "OpenCode plugin for CodeGraph CPG-powered code analysis",
  "type": "module",
  "main": "src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "CHANGELOG.md",
    "client-intent-contract.json"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "tsc"
  },
  "keywords": [
    "opencode",
    "codegraph",
    "cpg",
    "code-analysis",
    "security"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": ">=1.2.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.8.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.2.0"
  }
}
